using System.Collections.Generic;
using UnityEngine;
namespace Blocklands {
 public class CrystalGate:MonoBehaviour {
  Sandbox game;public bool Museum;public bool Open{get;private set;}public float Width{get;private set;}Transform left,right;float amount;
  public void Initialize(Sandbox g,Vector3 basePoint,float width,float height,bool museum){game=g;Museum=museum;Width=width;transform.position=basePoint;var a=gameObject.AddComponent<RoyalArt>();Color frame=new Color(.98f,.75f,.88f),crystal=new Color(.83f,.4f,.7f);a.Piece("水晶门框",new Vector3(0,height+.2f,0),new Vector3(width+1,.4f,.7f),frame,PrimitiveType.Cube,true);foreach(float x in new[]{-width/2-.3f,width/2+.3f})a.Piece("水晶门柱",new Vector3(x,height/2,0),new Vector3(.6f,height,.7f),frame,PrimitiveType.Cube,true);left=a.Piece("左水晶门",new Vector3(-width/4,height/2,0),new Vector3(width/2,height,.45f),crystal,PrimitiveType.Cube,true);right=a.Piece("右水晶门",new Vector3(width/4,height/2,0),new Vector3(width/2,height,.45f),crystal,PrimitiveType.Cube,true);}
  public bool Near(Vector3 p)=>Mathf.Abs(p.y-transform.position.y)<8&&Vector2.Distance(new Vector2(p.x,p.z),new Vector2(transform.position.x,transform.position.z))<11;
  public void Set(bool value){Open=value;}
  void Update(){amount=Mathf.MoveTowards(amount,Open?1:0,Time.deltaTime*1.4f);float w=(left.localScale.x+.01f);left.localPosition=new Vector3(-w/2-w*.92f*amount,left.localPosition.y,0);right.localPosition=new Vector3(w/2+w*.92f*amount,right.localPosition.y,0);}
 }
 public partial class MuseumLift:MonoBehaviour {
  Sandbox game;Transform car,left,right;Material glass;float open=1,dwell;int target;public bool Menu;public int Choice,Floor;public const int Floors=20;
  public static float FloorY(int f)=>16+Mathf.Clamp(f,0,19)*3;
  public bool Inside{get{Vector3 p=game.Player.transform.position-car.position;return Mathf.Abs(p.x)<1.3f&&Mathf.Abs(p.z)<1.3f&&p.y>-.25f&&p.y<2.5f;}}
  public bool Near(Vector3 p)=>Vector2.Distance(new Vector2(p.x,p.z),new Vector2(10,29))<4;
  public void Initialize(Sandbox g){game=g;car=new GameObject("博物馆透明电梯轿厢").transform;car.SetParent(transform);car.position=new Vector3(10,16,29);var a=car.gameObject.AddComponent<RoyalArt>();Color pink=new Color(.86f,.5f,.72f),gold=new Color(.95f,.75f,.3f);a.Piece("地板",new Vector3(0,-.1f,0),new Vector3(2.8f,.2f,2.8f),pink,PrimitiveType.Cube,true);a.Piece("轿顶",new Vector3(0,2.75f,0),new Vector3(2.8f,.15f,2.8f),gold);glass=new Material(Resources.Load<Shader>("GlassPane"));glass.color=new Color(.58f,.84f,.97f,.2f);Transform G(string n,Vector3 p,Vector3 s){var t=a.Piece(n,p,s,Color.white,PrimitiveType.Cube,true);t.GetComponent<Renderer>().sharedMaterial=glass;return t;}foreach(float x in new[]{-1.35f,1.35f})G("玻璃侧墙",new Vector3(x,1.35f,0),new Vector3(.08f,2.7f,2.7f));G("玻璃后墙",new Vector3(0,1.35f,1.35f),new Vector3(2.7f,2.7f,.08f));left=G("左门",new Vector3(-.68f,1.35f,-1.35f),new Vector3(1.35f,2.7f,.08f));right=G("右门",new Vector3(.68f,1.35f,-1.35f),new Vector3(1.35f,2.7f,.08f));}
  public void Toggle(){if(!Inside){target=Mathf.Clamp(Mathf.RoundToInt((game.Player.transform.position.y-16)/3),0,19);dwell=Time.time+.3f;game.Notice="博物馆电梯正到本层。";return;}Menu=!Menu;Choice=Floor;game.Notice=Menu?"博物馆电梯：↑↓选择1—20层，Enter确认。":"电梯面板关闭。";}
  public void Confirm(){if(!Inside){Menu=false;game.Notice="先走进电梯轿厢，再选择楼层。";return;}target=Mathf.Clamp(Choice,0,19);Menu=false;dwell=Time.time+.35f;game.Notice="博物馆电梯前往第"+(target+1)+"层。";}
  void Update(){if(game==null||game.Paused)return;bool moving=Mathf.Abs(car.position.y-FloorY(target))>.02f;float want=moving&&Time.time>dwell?0:1;open=Mathf.MoveTowards(open,want,Time.deltaTime*2);left.localPosition=new Vector3(-.68f-open*1.35f,1.35f,-1.35f);right.localPosition=new Vector3(.68f+open*1.35f,1.35f,-1.35f);if(!moving||open>.01f)return;bool passenger=Inside;Vector3 before=car.position;car.position=Vector3.MoveTowards(car.position,new Vector3(10,FloorY(target),29),Time.deltaTime*7);if(passenger)game.Player.Carry(car.position-before);if(Mathf.Abs(car.position.y-FloorY(target))<.02f){Floor=target;dwell=Time.time+.8f;}}
  void OnDestroy(){if(glass!=null)Destroy(glass);}
 }
 public class MuseumPerson:MonoBehaviour {Vector3 home;float seed;public void Initialize(Vector3 p,float s){home=p;seed=s;transform.position=p;}void Update(){transform.position=home+new Vector3(Mathf.Sin(Time.time*.4f+seed),0,Mathf.Cos(Time.time*.33f+seed))*.7f;}}
 public class MuseumGuard:MonoBehaviour {Sandbox game;CastleSystem castle;Vector3 home;public void Initialize(Sandbox g,CastleSystem c,Vector3 p){game=g;castle=c;home=p;transform.position=p;}void Update(){if(game==null||game.Paused)return;Vector3 goal=Time.time<castle.MuseumAlarmUntil?game.Player.transform.position:home;goal.y=transform.position.y;transform.position=Vector3.MoveTowards(transform.position,goal,Time.deltaTime*(Time.time<castle.MuseumAlarmUntil?4.5f:1.5f));Vector3 d=goal-transform.position;d.y=0;if(d.sqrMagnitude>.01f)transform.rotation=Quaternion.LookRotation(d);if(Time.time<castle.MuseumAlarmUntil&&Vector3.Distance(transform.position,game.Player.transform.position)<1.45f)game.Damage(.5f,"被博物馆保安追上",Vector3.Distance(transform.position,game.Player.transform.position));}}
 public partial class CastleSystem {
