   for(int i=0;i<8;i++){int f=i*19/7;Vector3 p=new Vector3(i%2==0?4:10,MuseumLift.FloorY(f),29+i%3*7);var root=new GameObject("博物馆保安 "+(i+1)).transform;root.SetParent(transform);var art=root.gameObject.AddComponent<RoyalArt>();art.Piece("蓝色制服",new Vector3(0,1,0),new Vector3(.65f,.9f,.4f),new Color(.15f,.3f,.65f));art.Piece("头",new Vector3(0,1.72f,0),new Vector3(.5f,.5f,.45f),new Color(.85f,.63f,.48f),PrimitiveType.Sphere);foreach(float x in new[]{-.12f,.12f})art.Piece("眼睛",new Vector3(x,1.77f,.22f),Vector3.one*.06f,Color.black,PrimitiveType.Sphere);root.gameObject.AddComponent<MuseumGuard>().Initialize(Game,this,p);}
   PalaceSign(new Vector3(56,20,2.6f),"粉晶医院",0,.12f);PalaceSign(new Vector3(56,20,42.6f),"森林警察局",0,.12f);PalaceSign(new Vector3(8,20,2.6f),"森林小店",0,.12f);nextProcession=Time.time+15;palacePrincess=transform.Find("公主");
  }
  public bool ToggleGate(){Vector3 p=Game.Player.transform.position;if(museumGate.Near(p)&&p.x<14){if(!museumTicket&&!Game.RoyalIdentity){Game.Notice="博物馆先按L购买50元门票。";return true;}museumGate.Set(!museumGate.Open);return true;}if(palaceGate.Near(p)){palaceGate.Set(!palaceGate.Open);Game.Notice=palaceGate.Open?"粉晶大门正在打开。":"粉晶大门正在关闭。";return true;}return false;}
  public bool MuseumLiftKey(){if(!museumLift.Near(Game.Player.transform.position)&&!museumLift.Menu)return false;museumLift.Toggle();return true;}
  public bool MuseumStep(int delta){if(!InMuseum(Game.Player.transform.position)||Vector2.Distance(new Vector2(Game.Player.transform.position.x,Game.Player.transform.position.z),new Vector2(4,29))>4)return false;int f=Mathf.Clamp(Mathf.RoundToInt((Game.Player.transform.position.y-16)/3)+delta,0,19);Game.Player.Teleport(new Vector3(4,MuseumLift.FloorY(f),30));Game.Notice="博物馆楼梯：第"+(f+1)+"层。";return true;}
  public bool MuseumMenuKeys(){if(museumLift==null||!museumLift.Menu)return false;if(Input.GetKeyDown(KeyCode.Escape)){museumLift.Toggle();return true;}if(Input.GetKeyDown(KeyCode.UpArrow))museumLift.Choice=(museumLift.Choice+19)%20;if(Input.GetKeyDown(KeyCode.DownArrow))museumLift.Choice=(museumLift.Choice+1)%20;if(Input.GetKeyDown(KeyCode.Return))museumLift.Confirm();return true;}
